-- Курс 4: Легкая беременность
INSERT INTO courses (title, description, is_public, price, author_id, is_active, cover_image_url, contraindications, recommendations, target_audience, course_basis, class_basis, bonuses)
SELECT
    'Легкая беременность',
    'Безопасная программа для подготовки тела к родам и комфортного протекания беременности. Снимаем напряжение с поясницы, учимся правильно дышать и расслабляться, чтобы роды прошли мягче и спокойнее.',
    false, 4000,
    (SELECT id FROM users WHERE email = 'admin@test.ru'),
    true,
    '/images/Course4.jpg',
    'Угроза прерывания беременности.|||Предлежание плаценты.|||Кровотечения на любом сроке.|||Повышенный тонус матки без разрешения врача.|||Многоплодная беременность с осложнениями.|||Тяжелый гестоз и эклампсия.',
    'Заниматься только при хорошем самочувствии.|||Следить за пульсом и не превышать рекомендованную нагрузку.|||Получить разрешение от акушера-гинеколога перед стартом.|||Пить воду до и после занятия.|||Избегать упражнений на спине после второго триместра.|||Заниматься в проветренном помещении в удобной одежде.',
    'Хочется подготовить тело к родам осознанно и без страха.|||Беспокоят отёки и тяжесть в ногах.|||Появились боли в спине и пояснице.|||Нужно научиться правильно дышать в схватках и потугах.|||Хочется сохранить подвижность и лёгкость до самых родов.|||Важно укрепить мышцы тазового дна и подготовить промежность.',
    'Физиология беременности по триместрам.|||Принципы безопасного движения для будущей мамы.|||Дыхательные техники для каждого этапа родов.|||Укрепление глубоких мышц кора и тазового дна.|||Подготовка промежности к естественным родам.|||Расслабление и визуализация для спокойствия.',
    'Дыхание животом и боковое дыхание.|||Мягкая гимнастика для позвоночника и таза.|||Упражнения для снятия напряжения с поясницы.|||Укрепление ягодичных мышц и мышц тазового дна.|||Растяжка для облегчения отёков и судорог.|||Позы для расслабления и отдыха.',
    '[{"title": "Гайд", "description": "Полный список вещей в роддом с пояснениями", "icon": "file"}, {"title": "Аудио", "description": "Дыхательные практики для схваток и потуг", "icon": "audio"}, {"title": "Памятка", "description": "Позы для комфортных родов", "icon": "file"}]'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM courses WHERE title = 'Легкая беременность');

