    (m_id, 'МЕНОПАУЗА.', '', 'da3452f6f267137e8098402f08b92cec', 'IRbf1CgojA-7kgE7kCrPEA', 1),
    (m_id, 'ПЕРЕД СНОМ.', 'Опора под таз.', 'b50f41b7fcb2cf03123c2d088d576f9a', 'V68r3_qWr7f0_9OaWd_ntg', 2),
    (m_id, 'Самомассаж живота.', 'От запоров.', '832fa6bf43064cbdd1302a201fd885db', 'AkmrgD5VemgGkJbXA894lA', 3);
END $$;

-- =============================================================================
-- 4. ОСТАЛЬНЫЕ КУРСЫ 
-- =============================================================================
DO $$
DECLARE c_id int; m_id int;
BEGIN
    SELECT id INTO c_id FROM courses WHERE title = 'Восстановление после родов';
    IF c_id IS NULL THEN RETURN; END IF;

    -- Неделя 1: Мягкий старт и дыхание
    INSERT INTO modules (course_id, title, "order", week_number) VALUES (c_id, 'Мягкий старт и дыхание', 1, 1) RETURNING id INTO m_id;
    INSERT INTO lessons (module_id, title, description, video_embed_id, "order") VALUES
    (m_id, 'Диафрагмальное дыхание для активации кора', 'Учимся дышать животом, чтобы мягко включить глубокие мышцы. Это основа всего восстановления. Выполняется лежа на спине с согнутыми ногами. Никакого напряжения шеи и плеч.', 'eeec3876368b57fcee9033f377b78f96', 1),
    (m_id, 'Боковое дыхание для расширения ребер', 'Восстанавливаем подвижность грудной клетки после беременности. Упражнение помогает снять зажимы в диафрагме и улучшить насыщение тканей кислородом.', '7e8c5681487cd383d46a513aee7d0601', 2),
    (m_id, 'Расслабление тазового дна на выдохе', 'Учимся отпускать напряжение в промежности. Это критически важно перед тем, как приступать к укрепляющим упражнениям. Мягкая практика лежа с визуализацией.', '70ef5b8c45818ee28152174035fcf490', 3),
    (m_id, 'Мягкая мобилизация стоп и голеностопа', 'Запускаем лимфоток и снимаем отечность ног. Простые круговые движения, сгибания и разгибания стоп. Подходит с первых дней после родов.', 'a34d5132da9445515f6948846a6b8f17', 4);

    -- Неделя 2: Диастаз и глубокая мускулатура
    INSERT INTO modules (course_id, title, "order", week_number) VALUES (c_id, 'Диастаз и глубокая мускулатура', 2, 2) RETURNING id INTO m_id;
    INSERT INTO lessons (module_id, title, description, video_embed_id, "order") VALUES
    (m_id, 'Что такое диастаз и как его оценить', 'Теоретический урок. Разбираем анатомию белой линии живота. Учимся самостоятельно измерять ширину диастаза в домашних условиях. Понимаем, какие цифры считать нормой.', 'e44cd2c3ff35ef42295da830f480030e', 1),
    (m_id, 'Активация поперечной мышцы живота', 'Ключевое упражнение для закрытия диастаза. Учимся изолированно включать поперечную мышцу, не напрягая прямую мышцу живота. Техника выполнения лежа с контролем рукой.', '850e83ac57e788316f71366755a64dd5', 2),
    (m_id, 'Безопасные упражнения для пресса', 'Разбираем, какие упражнения можно выполнять при диастазе, а какие категорически запрещены. Демонстрация безопасных вариантов скручиваний и планок.', '5c3b90c21f87403581ccd51d8f6f41e7', 3),
    (m_id, 'Координация дыхания и движения', 'Соединяем выдох с активацией глубокого кора. Учимся выполнять бытовые движения с защитой белой линии живота. Практика подъема головы и рук без нагрузки на диастаз.', '54ee29ae0f51d5997562c5495ae35bcc', 4);

    -- Неделя 3: Работа с рубцом
    INSERT INTO modules (course_id, title, "order", week_number) VALUES (c_id, 'Работа с рубцом', 3, 3) RETURNING id INTO m_id;
    INSERT INTO lessons (module_id, title, description, video_embed_id, "order") VALUES
    (m_id, 'Массаж рубца: первый этап', 'Учимся поверхностно массировать шрам после кесарева или эпизиотомии. Правила безопасности, частота и длительность массажа. Какие масла и кремы использовать для увлажнения.', 'cce7262fc30fb1f0c4bb9d65999b3593', 1),
    (m_id, 'Мобилизация тканей вокруг рубца', 'Второй этап работы со шрамом. Смещаем ткани в разных направлениях для восстановления подвижности. Предотвращаем образование спаек и чувства стянутости.', '209de268fb6ab2e4d2298bf018751bdb', 2),
    (m_id, 'Работа с чувствительностью рубца', 'Техники десенсибилизации. Используем разные текстуры тканей, ватные диски, мягкую щетку. Убираем неприятные ощущения и онемение в области шва.', '4bc97662acb81aa004c24674760255b8', 3),
    (m_id, 'Интеграция рубца в движение', 'Финальный этап. Учимся двигаться так, чтобы рубец не ограничивал подвижность. Наклоны, повороты, потягивания с контролем ощущений в области шва.', '951325b973a117f33a534cf6f53a649a', 4);

    -- Неделя 4: Возвращение к активности
    INSERT INTO modules (course_id, title, "order", week_number) VALUES (c_id, 'Возвращение к активности', 4, 4) RETURNING id INTO m_id;
    INSERT INTO lessons (module_id, title, description, video_embed_id, "order") VALUES
    (m_id, 'Укрепление ягодичных мышц', 'Восстанавливаем силу ягодиц для поддержки поясницы и таза. Ягодичный мост с акцентом на выдох. Прогрессия от статики к динамике.', 'b1cd3963f4e27239c0344b811162b2ba', 1),
    (m_id, 'Биомеханика подъема ребенка', 'Как правильно брать малыша на руки, носить и класть обратно. Разбираем технику приседа и выпада. Защищаем спину и тазовое дно от перегрузки.', 'eeec3876368b57fcee9033f377b78f96', 2),
    (m_id, 'Прогулка с коляской без боли', 'Настраиваем осанку во время прогулок. Правильное положение рук на ручке коляски. Упражнения для расслабления плеч и шеи после долгой ходьбы.', '7e8c5681487cd383d46a513aee7d0601', 3),
    (m_id, 'Эргономика кормления и быта', 'Организуем место для кормления без напряжения спины. Позы для отдыха и сна. Как мыть посуду и гладить белье с пользой для осанки.', '70ef5b8c45818ee28152174035fcf490', 4);

     INSERT INTO modules (course_id, title, "order", week_number) VALUES (c_id, 'Бонусы', 5, 5) RETURNING id INTO m_id;
    INSERT INTO lessons (module_id, title, description, video_embed_id, "order") VALUES
    (m_id, 'Вебинар: разбор типичных ошибок при восстановлении', 'Запись живого эфира с ответами на частые вопросы. Какие ошибки допускают мамы в первые месяцы и как их избежать. Примеры из практики.', 'a34d5132da9445515f6948846a6b8f17', 1),
    (m_id, 'Мастер-класс: самомассаж стоп и голеней', 'Техники расслабления уставших ног. Работа с триггерными точками и отечностью. Используем массажный мяч и собственные руки.', 'e44cd2c3ff35ef42295da830f480030e', 2),
    (m_id, 'Видеоурок: дневник самодиагностики диастаза', 'Готовая таблица для отслеживания прогресса. Как измерять диастаз раз в неделю и фиксировать результаты. Подробный видеоразбор заполнения.', '850e83ac57e788316f71366755a64dd5', 3),
    (m_id, 'Медитация для сна и восстановления', 'Видеопрактика на 15 минут. Помогает снять накопленное за день напряжение и подготовить тело к глубокому сну. Визуализация и дыхание.', '5c3b90c21f87403581ccd51d8f6f41e7', 4);
END $$;


-- ============================================================
-- КУРС: Женское здоровье 360 (БЕСПЛАТНЫЙ, 0 руб)
-- ============================================================
DO $$
DECLARE c_id int; m_id int;
BEGIN
    SELECT id INTO c_id FROM courses WHERE title = 'Женское здоровье 360';
    IF c_id IS NULL THEN RETURN; END IF;

    -- Неделя 1: Знакомство с методом
    INSERT INTO modules (course_id, title, "order", week_number) VALUES (c_id, 'Знакомство с методом', 1, 1) RETURNING id INTO m_id;
    INSERT INTO lessons (module_id, title, description, video_embed_id, "order") VALUES
    (m_id, 'Кто я и почему женское здоровье', 'История физического терапевта Ольги Пимченко. Почему традиционная медицина не всегда дает ответы на женские вопросы. С какими проблемами я работаю и как выстроен мой подход.', 'eeec3876368b57fcee9033f377b78f96', 1),
    (m_id, 'Как устроено женское тело: базовые принципы', 'Разбираем анатомию простым языком. Тазовое дно, диафрагма, мышцы кора — как они связаны между собой. Почему проблемы в одной зоне отражаются на всем теле.', '7e8c5681487cd383d46a513aee7d0601', 2),
    (m_id, 'Дневник наблюдения за телом: с чего начать', 'Учимся слышать сигналы своего организма. Какие ощущения отслеживать в течение дня. Как заполнять дневник и делать выводы.', '70ef5b8c45818ee28152174035fcf490', 3);

    -- Неделя 2: Дыхание и осанка
    INSERT INTO modules (course_id, title, "order", week_number) VALUES (c_id, 'Дыхание и осанка', 2, 2) RETURNING id INTO m_id;
    INSERT INTO lessons (module_id, title, description, video_embed_id, "order") VALUES
    (m_id, 'Дыхательная практика "Квадрат"', 'Учимся дышать в ритме 4-4-4-4. Это успокаивает нервную систему и мягко активирует глубокие мышцы. Практика сидя и лежа.', 'a34d5132da9445515f6948846a6b8f17', 1),
    (m_id, 'Мягкая гимнастика для шеи и плечевого пояса', 'Снимаем напряжение после рабочего дня. Наклоны, повороты, круговые движения. Работа с зонами, где чаще всего скапливается стресс.', 'e44cd2c3ff35ef42295da830f480030e', 2),
    (m_id, 'Упражнение "Тазовые часы" для расслабления поясницы', 'Представляем таз как циферблат и мягко двигаем им по кругу. Это снимает зажимы в крестце и улучшает подвижность поясничного отдела.', '850e83ac57e788316f71366755a64dd5', 3),
    (m_id, 'Связь дыхания и осанки: практический урок', 'Как положение тела влияет на глубину вдоха. Эксперимент: дышим в сутулой позе и с ровной спиной. Учимся находить свою оптимальную осанку.', '5c3b90c21f87403581ccd51d8f6f41e7', 4);

    -- Неделя 3: Тазовое дно и стресс
    INSERT INTO modules (course_id, title, "order", week_number) VALUES (c_id, 'Тазовое дно и стресс', 3, 3) RETURNING id INTO m_id;
    INSERT INTO lessons (module_id, title, description, video_embed_id, "order") VALUES
    (m_id, 'Как стресс влияет на мышцы малого таза', 'Разбираем связь кортизола и мышечного тонуса. Почему при хроническом стрессе тазовое дно постоянно напряжено. Как разорвать этот порочный круг.', '54ee29ae0f51d5997562c5495ae35bcc', 1),
    (m_id, 'Техника прогрессивной релаксации', 'Поочередно напрягаем и расслабляем все группы мышц. От стоп до лица. Учимся различать состояние напряжения и покоя в теле.', 'cce7262fc30fb1f0c4bb9d65999b3593', 2),
    (m_id, 'Активация стоп и баланс', 'Стопы — фундамент нашего тела. Простые упражнения для укрепления свода стопы и улучшения равновесия. Тренировка босиком на коврике.', '209de268fb6ab2e4d2298bf018751bdb', 3);

    -- Неделя 4: Безопасное движение и обзор программ
    INSERT INTO modules (course_id, title, "order", week_number) VALUES (c_id, 'Безопасное движение и обзор программ', 4, 4) RETURNING id INTO m_id;
    INSERT INTO lessons (module_id, title, description, video_embed_id, "order") VALUES
    (m_id, 'Принципы безопасного движения в быту', 'Как правильно вставать с кровати, поднимать сумки, наклоняться за ребенком. Базовые правила биомеханики для защиты спины и таза.', '4bc97662acb81aa004c24674760255b8', 1),
    (m_id, 'Визуализация и контакт с телом', 'Практика осознанности. Закрываем глаза и мысленно проходим по всему телу. Отмечаем зоны комфорта и дискомфорта. Учимся благодарить свое тело.', '951325b973a117f33a534cf6f53a649a', 2),
    (m_id, 'Обзор платных программ Ольги Пимченко', 'Рассказываю про курсы: Восстановление после родов, Легкая беременность, Реабилитация при РМЖ. Как выбрать подходящую программу и что вы получите.', 'b1cd3963f4e27239c0344b811162b2ba', 3);

    -- Бонусы
    INSERT INTO modules (course_id, title, "order", week_number) VALUES (c_id, 'Бонусы', 5, 5) RETURNING id INTO m_id;
    INSERT INTO lessons (module_id, title, description, video_embed_id, "order") VALUES
    (m_id, 'Видеогайд: как выбрать курс под свою проблему', 'Пошаговый алгоритм самодиагностики в видеоформате. Определяем свою основную зону дискомфорта и подбираем программу, которая даст максимальный результат.', 'eeec3876368b57fcee9033f377b78f96', 1),
    (m_id, 'Расслабляющая видеопрактика на 10 минут', 'Медитация с голосом Ольги и визуальным рядом. Можно включить перед сном или в перерыве между делами. Помогает перезагрузиться и снять накопленное напряжение.', '7e8c5681487cd383d46a513aee7d0601', 2),
    (m_id, 'Видеочек-лист: 5 маркеров женского здоровья', 'Пять простых тестов с видеоинструкцией. Оцениваем осанку, глубину дыхания, подвижность таза и напряжение тазового дна.', '70ef5b8c45818ee28152174035fcf490', 3);
END $$;

-- ============================================================
-- КУРС: Легкая беременность (ПЛАТНЫЙ, 4000 руб)
-- ============================================================
DO $$
DECLARE c_id int; m_id int;
BEGIN
    SELECT id INTO c_id FROM courses WHERE title = 'Легкая беременность';
    IF c_id IS NULL THEN RETURN; END IF;

    -- Неделя 1: Первый триместр
    INSERT INTO modules (course_id, title, "order", week_number) VALUES (c_id, 'Первый триместр: адаптация и дыхание', 1, 1) RETURNING id INTO m_id;
    INSERT INTO lessons (module_id, title, description, video_embed_id, "order") VALUES
    (m_id, 'Адаптация к новому состоянию', 'Как мягко принять изменения в теле. Психологический настрой и первые шаги. Режим активности в первом триместре: что можно и что нельзя.', 'a34d5132da9445515f6948846a6b8f17', 1),
    (m_id, 'Дыхание против токсикоза и усталости', 'Техники дыхания, которые помогают справиться с тошнотой и головокружением. Короткие практики на 2-3 минуты для восстановления сил.', 'e44cd2c3ff35ef42295da830f480030e', 2),
    (m_id, 'Расслабление и улучшение сна', 'Позы для отдыха в первом триместре. Техника прогрессивной релаксации для беременных. Как организовать спальное место для комфортного сна.', '850e83ac57e788316f71366755a64dd5', 3);

    -- Неделя 2: Второй триместр
    INSERT INTO modules (course_id, title, "order", week_number) VALUES (c_id, 'Второй триместр: сила и подвижность', 2, 2) RETURNING id INTO m_id;
    INSERT INTO lessons (module_id, title, description, video_embed_id, "order") VALUES
    (m_id, 'Укрепление ног против отеков', 'Упражнения для активации венозной помпы. Подъемы на носки, круговые движения стопами, мягкие приседания с опорой. Уменьшаем отечность к вечеру.', '5c3b90c21f87403581ccd51d8f6f41e7', 1),
    (m_id, 'Мобилизация грудного отдела', 'Раскрываем грудную клетку для лучшего дыхания. Упражнения сидя на стуле и с опорой на стену. Профилактика сутулости по мере роста живота.', '54ee29ae0f51d5997562c5495ae35bcc', 2),
    (m_id, 'Подвижность таза и крестца', 'Круговые движения тазом, наклоны вперед с опорой. Упражнение "бабочка" для раскрытия тазобедренных суставов. Готовим таз к родам заранее.', 'cce7262fc30fb1f0c4bb9d65999b3593', 3),
    (m_id, 'Укрепление ягодичных мышц', 'Ягодичный мост и его вариации для беременных. Боковые подъемы ног лежа. Сильные ягодицы снижают нагрузку на поясницу.', '209de268fb6ab2e4d2298bf018751bdb', 4);

    -- Неделя 3: Третий триместр
    INSERT INTO modules (course_id, title, "order", week_number) VALUES (c_id, 'Третий триместр: подготовка к родам', 3, 3) RETURNING id INTO m_id;
    INSERT INTO lessons (module_id, title, description, video_embed_id, "order") VALUES
    (m_id, 'Облегчение боли в спине', 'Упражнения с опорой на фитбол и стену. Поза "кошка-корова" стоя на четвереньках. Снимаем напряжение с поясницы на большом сроке.', '4bc97662acb81aa004c24674760255b8', 1),
    (m_id, 'Подготовка промежности к родам', 'Техники массажа промежности. Упражнения для эластичности тканей. Дыхание для расслабления тазового дна в момент прохождения головки.', '951325b973a117f33a534cf6f53a649a', 2),
    (m_id, 'Дыхание в схватках: практика', 'Отрабатываем разные типы дыхания для разных фаз родов. Медленное дыхание для ранних схваток. Частое дыхание для активной фазы. Техника "задувания свечи".', 'b1cd3963f4e27239c0344b811162b2ba', 3),
    (m_id, 'Позы для комфортных родов', 'Вертикальные позы с опорой на партнера или фитбол. Поза на четвереньках. Коленно-локтевая поза. Практикуем смену позиций.', 'eeec3876368b57fcee9033f377b78f96', 4);

    -- Неделя 4: Бонусы
    INSERT INTO modules (course_id, title, "order", week_number) VALUES (c_id, 'Бонусы', 4, 4) RETURNING id INTO m_id;
    INSERT INTO lessons (module_id, title, description, video_embed_id, "order") VALUES
    (m_id, 'Видеогайд: полный список вещей в роддом', 'Подробный видеообзор всего необходимого для мамы и малыша. С пояснениями, зачем нужна каждая вещь. Разделение на сумки: в родзал, в палату, на выписку.', '7e8c5681487cd383d46a513aee7d0601', 1),
    (m_id, 'Видеоурок: дыхательные практики для схваток', 'Видеозапись с демонстрацией дыхания. Можно включить в родах и следовать инструкциям. Помогает не сбиваться с ритма дыхания.', '70ef5b8c45818ee28152174035fcf490', 2),
    (m_id, 'Видеопамятка: позы для комфортных родов', 'Наглядное видео с демонстрацией позиций. Партнер сможет помогать вам менять позы. Посмотрите заранее и возьмите с собой уверенность.', 'a34d5132da9445515f6948846a6b8f17', 3),
