SELECT insert_review_safe('user2@test.ru', 'Восстановление после родов', 'У меня было кесарево сечение, и я боялась вообще что-либо делать. Шрам болел, живот висел фартуком. Ольга показала, как правильно массировать рубец и включать мышцы. Уже через 6 недель я спокойно вставала с кровати без боли. Очень грамотный курс, рекомендую всем мамам после КС.', 5);
SELECT insert_review_safe('user3@test.ru', 'Восстановление после родов', 'Курс хороший, но мне не хватило обратной связи. Видеоуроки записаны понятно, но иногда хотелось уточнить, правильно ли я делаю упражнение. В целом результатом довольна — диастаз с 3 см уменьшился до 1 см за два месяца.', 4);
SELECT insert_review_safe('user4@test.ru', 'Восстановление после родов', 'Купила курс по рекомендации подруги. Понравилось, что уроки разбиты по неделям и не нужно думать, что делать сегодня. Все структурировано. Отдельное спасибо за уроки про массаж шрама — до курса я вообще не знала, что с рубцом надо работать.', 5);

