SELECT insert_review_safe('user6@test.ru', 'Женское здоровье 360', 'Хороший вводный курс для тех, кто ничего не знает про тазовое здоровье. Мне понравилась практика "Тазовые часы" — реально помогает расслабить поясницу после офиса. Жаль, что бесплатный доступ ограничен, но оно и понятно.', 4);
SELECT insert_review_safe('user7@test.ru', 'Женское здоровье 360', 'Прохожу курс третий день. Очень нравится подача материала — спокойно, без запугиваний и лишней анатомии. Упражнения простые, но чувствую, как тело отзывается. Пока ставлю 4 звезды, жду продолжения.', 4);

