SELECT insert_review_safe('user8@test.ru', 'Легкая беременность', 'Проходила курс на втором и третьем триместре. Это лучшее вложение в свою беременность! Спина болела сильно, а после упражнений становилось легче. Дыхательные техники очень пригодились в родах — я реально дышала так, как учила Ольга, и это помогло.', 5);
SELECT insert_review_safe('user9@test.ru', 'Легкая беременность', 'Беременность протекала тяжело, был тонус и угроза. Гинеколог разрешила только дыхание и легкую гимнастику. Этот курс подошел идеально — все упражнения щадящие, ничего опасного. Родила сама, без разрывов. Огромное спасибо!', 5);
SELECT insert_review_safe('user10@test.ru', 'Легкая беременность', 'Хороший курс, но мне показался немного затянутым. Некоторые уроки можно было бы объединить. Понравились бонусы — список в роддом реально выручил, ничего не забыла. Позы для родов тоже пригодились.', 4);
SELECT insert_review_safe('user11@test.ru', 'Легкая беременность', 'Понравилось, что курс идет по триместрам. Сразу видно, что автор разбирается в физиологии беременных. Делала упражнения каждый день, и это помогло сохранить подвижность до самых родов. Подружки удивлялись, как я легко хожу на девятом месяце!', 5);

