SELECT insert_review_safe('user13@test.ru', 'Реабилитация при РМЖ', 'Бесплатный курс, который реально помогает. После операции была депрессия и страх двигаться. Уроки про лимфостаз и массаж рубца — самые полезные для меня. Жаль, что нет очных консультаций, но и онлайн-формат очень выручил.', 5);
